+4DialogPtr	equ EventPtr+4ReturnFlag	equ DialogPtr+4	phd	; save d	phb	; save b	phk	; set b to our bank	plb	tsc	; turn stack into zp	tcd	lda #0	sta WhereInModal	stz ReturnFlag	; we always return false	lda [EventPtr]	cmp #1	; only care about mouse down	beq KeepLooking1	brl AllDoneKeepLooking1	pha	PushLong #FoundControl	ldy #oWhere+2	lda [EventPtr],y	pha	dey	dey	lda [EventPtr],y	pha	PushLong VDialogPtr	_FindControl	pla	bne KeepLooking2	brl AllDoneKeepLooking2	lda FoundControl	cmp ListControl1	bne NotList1	lda FoundControl+2	cmp ListControl1+2	bne NotList1	lda #1	sta WhereInModal	brl DoItNotList1	lda FoundControl	cmp ListControl2	bne NotList2	lda FoundControl+2	cmp ListControl2+2	bne NotList2	lda #2	sta WhereInModal	brl DoItNotList2	lda FoundControl	cmp ScrollControl1	bne NotScroll1	lda FoundControl+2	cmp ScrollControl1+2	bne NotScroll1	brl DoItNotScroll1	lda FoundControl	cmp ScrollControl2	bne NotScroll2	lda FoundControl+2	cmp ScrollControl2+2	beq DoItNotScroll2	brl AllDoneDoIt	jsr RestoreRefCons	pha	ldy #oWhere+2	lda [EventPtr],y	pha	dey	dey	lda [EventPtr],y	pha	PushLong #$FFFFFFFF	PushLong FoundControl	_TrackControl	pla	jsr ZeroRefCons	lda WhereInModal	cmp #1	beq DoInTypeList	cmp #2	beq BranchLong	brl AllDoneBranchLong		;	brl DoInPrNameListDoInTypeList		;	lda >AppleTalkOn	bne AppleTalkIsOn1	brl AllDoneAppleTalkIsOn1	jsr WaitCursor	PushLong #ListRec1	PushWord EntrySize1	PushLong #TempPrType	jsr GetSelFromList	PushLong #CurrentPrinter	PushLong #TempPrType	jsr EqualString	bne PrinterChanged	brl NoPrChangePrinterChanged	jsr UnloadCurrentPrinter	PushLong #TempPrType	PushLong #CurrentPrinter	jsr CopyString	pha	_DevIsItSafe	pla	beq SlotSevenNotAT	stz ListCount2	pea 0	pea 0	PushLong #ListRec2	_NewList	jsr GetNewPrNames	PushLong #ListRec2	PushWord EntrySize2	PushLong #CurrentNetName	jsr GetSelFromList	bcs NothingSelected	PushLong #CurrentPrinter	PushLong #CurrentPrinter1	jsr CopyString	PushLong #TempZone	PushLong #CurrentZoneName	jsr CopyStringNothingSelected		;SlotSevenNotAT		;	jsr InitCursor	brl AllDoneDoInPrNameList	jsr WaitCursor	lda >AppleTalkOn	bne AppleTalkIsOn2	PushLong #ListRec2	PushWord EntrySize2	PushLong #CurrentPort	jsr GetSelFromList	PushLong #CurrentPort	PushLong #CurrentDriver	jsr EqualString	bne PortChanged	brl NoPrChangePortChanged	lda #0	sta CheckPort	jsr UnloadCurrentPort	PushLong #CurrentPort	PushLong #CurrentDriver	jsr CopyString	brl NoPrChangeAppleTalkIsOn2	PushLong #CurrentNetName	PushLong #TempNetName	jsr CopyString	PushLong #ListRec2	PushWord EntrySize2	PushLong #CurrentNetName	jsr GetSelFromList	PushLong #TempZone	; HY changed 6/6/88, now comparing zones instead of net name	PushLong #CurrentZoneName ; fixes problem that arises when the net name is the	jsr EqualString	; the same, but you are in a different zone. The previous	bne GetNewZone	; way would never recognize the zone change.		PushLong #CurrentNetName ; if no zone changed but printer name selection has 	PushLong #TempNetName    ; changed then we also want to save the current 	jsr EqualString	     ; printer driver change.	bne GetNewZone		bra NoPrChangeGetNewZone	PushLong #TempZone	PushLong #CurrentZoneName	jsr CopyString	PushLong #TempPrType	PushLong #CurrentPrinter1	jsr CopyStringNoPrChange	jsr InitCursorAllDone	lda >CheckPort	bne ItsBeenChecked	pha	_DevIsItSafe	pla	bne ItsSafe		lda >AppleTalkOn	beq NotAT		PushWord #4	; put up the 'AppleTalk not selected in the 	jsl PostAlert	; control panel' message.	pla	bra ItsSafeNotAT	pha	pha	_DevPrChangedItsSafe	lda #1	sta >CheckPort	jsr InitCursorItsBeenChecked	plb	; restore b	pld	; restore d	phb	; put extra byte on	stack	pla	; pull long into x,a	plx	ply	; strip 6 words	ply	ply	ply	ply	ply	phx	pha	plb	; pull extra byte	rtl	; doneFoundControl	DS.B 4	ENDP****************************************************************** DeRefandLock** Space for pointer	    LONG* Handle list	    LONG** Lock the handle to the list and put pointer in list record******************************************************************	EXPORT DerefandLockDerefandLock	PROC	DefineStackorigD	wordrts	wordHandle	longPointer	long	phd	tsc	tcd	ldy #$0004	; first lock the handle	lda [Handle],y	ora #$8000	sta [Handle],y	dey	dey	lda [Handle],y	sta Pointer+2	lda [Handle]	sta Pointer	pld	; restore direct	pla	; save rts adr	plx	; get rid of handle	plx	pha	; push rts adr back	on stack	rts	ENDP******************************************************************** InitThisList**        Space for result*        NumberofItems*        ItemSize*        PointerToFirstItem*        PointerToCurrent selection*   TOS  --** Goes through the list set and clearing the selection bit* as required.  Returns the flag to indicate if any are set*******************************************************************	EXPORT InitThisListInitThisList	PROC	DefineStackOrigD	word	1Rts	word	3CurrentPtr	LONG	5ItemPtr	LONG	9ItemSize	wordCounter	word	phd	tsc	tcd	lda #False	sta SomeThingFound	lda Counter	bne NextItem	brl AllIsWellNextItem	lda ItemPtr	clc	adc #5	tax	lda ItemPtr+2	adc #0	pha	phx	PushLong CurrentPtr	jsr EqualString	beq ThisIsItSetNotSelectedBit	ldy #4	lda [ItemPtr],y	and #%1111111101111111	sta [ItemPtr],y	bra ItsSetThisIsIt	lda DiffZone	bne SetNotSelectedBit		lda #True1	sta SomeThingFound	ldy #4	lda [ItemPtr],y	ora #$0080	sta [ItemPtr],y	lda #$FFFF	sta 5,sItsSet	dec Counter	beq AllIsWell	lda ItemPtr	clc	adc ItemSize	sta ItemPtr	lda ItemPtr+2	adc #0	sta ItemPtr+2	bra NextItemAllIsWell	pld	; restore direct	pla	; save rts adr	plx	; throw away 12 bytes	plx	plx	plx	plx	plx	pha	; put back rts	rts	ENDP******************************************************************** GetSelFromList**    Pointer to List Record    LONG*    Size of entry	           WORD*    DestLoc for String        LONG** This routine gets	the selected item from the specified list* and puts it in the specified location.** It moves entry size bytes to destination, not just the* length of the string.*******************************************************************	EXPORT GetSelFromListGetSelFromList	PROC	DefineStackOrigD	wordRTS	wordDestPtr	LONGEntrySize	WORDListPtr	LONG	phd	tsc	tcd	pha	pha	PushLong #0	; start at first member	pei ListPtr+2	pei ListPtr	_NextMember	lda 1,s	ora 3,s	bne FoundIt1	pla	pla	sec	bra SkipThisShit1FoundIt1	pla	clc	adc #5	sta ListPtr	pla	adc #0	sta ListPtr+2	sep #$30	longa off	longi off	lda EntrySize	sec	sbc #6	; 5 for list mgr junk and 1 to	tay	; be size - 1Loop	lda [ListPtr],y	sta [DestPtr],y	dey	bpl Loop	rep #$30	longa on	longi on	clcSkipThisShit1	pld	pla	plx	plx	plx	plx	plx	pha	rts	ENDP******************************************************************** InitHandles********************************************************************	EXPORT InitHandlesInitHandles	PROC	stz ZoneHandle	stz ZoneHandle+2	stz PrinterHandle	stz PrinterHandle+2	rts	ENDP******************************************************************** DisposeOfHandles********************************************************************	EXPORT DisposeOfHandlesDisposeOfHandles	PROC; removed unlock before dispose	PushLong PrinterHandle	_DisposeHandle	PushLong ZoneHandle	_DisposeHandle	rts	ENDP******************************************************************** ChooserDATA** The dialog looks something like:**     Printer Type:		           - ATLine1**     -------------------------------------------  - ATLine2*     |		        |*     |     Printer	Types List	        |*     |		        |*     -------------------------------------------  - ATLine3*     Printer Names:	           - ATLine4**     -------------------------------------------  - ATLine5*     |		        |*     |     Printer	Names List	        |*     |		        |*     -------------------------------------------  - ATLine6*     AppleTalk Zones:	           - ATLine7**     -------------------------------------------  - ATLine8*     |		        |*     |     AppleTalk Zones List	        |*     |		        |*     -------------------------------------------  - ATLine9*     |--|Appletalk	          |--|Direct Connect   - ATLine10*     |--|	          |--|*		           - ATLine11*     User Name:		           - ATLine12**     |	     |  | Cancel | |   OK   |*******************************************************************	EXPORT ChooserDataChooserData	PROC	EXPORT ATTemplateATTemplate	DC.W ATChooserTop	; top	EXPORT ATChooserLeftATChooserLeft	DC.W ATChooserLeft	; left	DC.W ATChooserTop+ATDialogHeight ; bottom	EXPORT ATChooserRightATChooserRight	DC.W ATChooserLeft+ATDialogWidth ; right	DC.W True1	; visible	DC.L 0	; ref con	DC.L ATItem1	; Ok button	DC.L ATItem2	; Cancel button	DC.L ATItem3	; Appletalk Zone string	DC.L 0000	EXPORT ATItem1ATItem1	DC.W 1	; id	DC.W ATLine5,ATOKStartX,ATLine6,ATOKStartX+ButSize	DC.W ButtonItem	; type	DC.L OKButtonStr	; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT ATItem2ATItem2	DC.W 2	; id	DC.W ATLine5,ATCancelStartX,ATLine6,ATCancelStartX+ButSize	DC.W ButtonItem	; type	DC.L CancelButtonStr ; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT ATItem3ATItem3	DC.W 3	; id	DC.W ATLine1,Margin,ATLine2,ATInnerBoxWidth	DC.W StatText+$8000	; type	DC.L ZoneNameStr	; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT ATListRecATListRec	DC.W ATLine3,Margin,ATLine4,Margin+ATInnerBoxWidth ; Zone name record	EXPORT ATListCountATListCount	DS.B 2	; number of members	in the list	DC.W 04	; number seen at once	DC.W $02	; list type single selection only	DC.W 1	; list start (first	seen)	DC.L 0	; space for control	DC.L MyDraw	; list draw (pointer to draw routine)	DC.W 10	; height of single item	EXPORT ATEntrySizeATEntrySize	DS.B 2	; size of list record	EXPORT ATAdrListATAdrList	DS.B 4	; pointer to the list itself	DC.L 0	; ref con	DC.L 0	; adr of color table for control	EXPORT TemplateTemplate	DC.W ChooserTop	; top	EXPORT ChooserLeftChooserLeft	DC.W ChooserLeft	; left	DC.W ChooserTop+DialogHeight ; bottom	EXPORT ChooserRightChooserRight		;	DC.W ChooserLeft+DialogWidth ; right	DC.W True1	; visible	DC.L 0	; ref con	DC.L item1	; Ok button	DC.L item2	; Cancel button	DC.L item3	; Zone... button	DC.L item4	; Title String: Chooser Printer..	DC.L item5	; Printer Type string	DC.L item6	; Printer Port string	DC.L item7	; AppleTalk radio button	DC.L item8	; Direct Conect radio button	DC.L item9	; 'User Name:' string	DC.L item10	; edit line item	DC.L 0000	EXPORT item1item1	DC.W 1	; id	DC.W Line15,OKStartX,Line16,OKStartX+ButSize	DC.W ButtonItem	; type	DC.L OKButtonStr	; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item2item2	DC.W 2	; id	DC.W Line15,CancelStartX,Line16,CancelStartX+ButSize	DC.W ButtonItem	; type	DC.L CancelButtonStr ; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item3item3	DC.W 3	; id	DC.W Line15,ZoneStartX,Line16,ZoneStartX+ButSize	DC.W ButtonItem	; type	DC.L ZoneButtonStr	; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item4item4	DC.W 4	; id	DC.W Line1,TitleMargin,Line2,InnerBoxWidth	DC.W StatText+$8000	; type	DC.L TitleStr	; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item5item5	DC.W 5	; id	DC.W Line3,Margin,Line4,InnerBoxWidth	DC.W StatText+$8000	; type	DC.L PrTypeStr	; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item6item6	DC.W 6	; id	DC.W Line7,Margin,Line8,Margin+InnerBoxWidth+15	DC.W StatText+$8000	; type	DC.L PrPortStr	; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item7item7	DC.W 7	; id	DC.W Line11,Margin,Line12,CancelStartX-1	DC.W RadioItem	; type	DC.L RadioString1	; item descreptor (Appletalk rad. but)	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item8item8	DC.W 8	; id	DC.W Line11,CancelStartX+33,Line12,Margin+InnerBoxWidth+23	DC.W RadioItem	; type	DC.L RadioString2	; item descreptor (Direct Conn rad. but)	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item9item9	DC.W 9	; id            	DC.W Line13,Margin,Line14,Margin+79	DC.W StatText+$8000	; type	DC.L UserNameStr	; item descreptor	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item10item10	DC.W 10	; id            	DC.W Line13,Margin+80,Line14,Margin+InnerBoxWidth+18	DC.W EditLine	; type	DC.L CurrentUser	; item descreptor	DC.W 15	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT ListRec1ListRec1	DC.W Line5,Margin,Line6,Margin+InnerBoxWidth ;Printer Type rect for direct Connect	EXPORT ListCount1ListCount1	DS.B 2	; number of members	in the list	DC.W 04	; number seen at once	DC.W $02	; list type single selection only	DC.W 1	; list start (first	seen)	DC.L 0	; space for control	DC.L MyDraw	; list draw (pointer to draw routine)	DC.W 10	; height of single item	EXPORT EntrySize1EntrySize1	DS.B 2	; size of list record	EXPORT AdrList1AdrList1	DS.B 4	; pointer to the list itself	DC.L 0	; ref con	DC.L 0	; adr of color table for control	EXPORT ListRec2ListRec2	DC.W Line9,Margin,Line10,Margin+InnerBoxWidth ; Printer Port rect for direct connect	EXPORT ListCount2ListCount2	DS.B 2	; number of members	in the list	DC.W 04	; number seen at once	DC.W $02	; list type single selection only	DC.W 1	; list start (first	seen)	DC.L 0	; space for control	DC.L MyDraw	; list draw (pointer to draw routine)	DC.W 10	; height of single item	EXPORT EntrySize2EntrySize2	DS.B 2	; size of list record	EXPORT AdrList2AdrList2	DS.B 4	; pointer to the list itself	DC.L 0	; ref con	DC.L 0	; adr of color table for control	EXPORT CheckPortCheckPort	DC.W 0	EXPORT DiffZoneDiffZone	DC.W 0; List Record Entry;; long reserved for	DAN; byte reserved for	DAN (memflag); 16 bytes      for	me (driver name);	ENDP******************************************************************* MyDraw** This routine draws the list item when	asked by the list mgr**       Ptr to Bounding Rect*       Ptr to member record*       Handle to list Control record*******************************************************************MyDraw	PROCOrigD	equ 1RTLAdr	equ OrigD+2CHandle	equ RTLAdr+3MemberPtr	equ CHandle+4RectPtr	equ MemberPtr+4	phd	tsc	tcd	phb	phk	plb	pei RectPtr+2	pei RectPtr	_EraseRect	ldy #2	lda [RectPtr],y	clc	adc #2	pha	ldy #4	lda [RectPtr],y	dec a	dec a	pha	_MoveTo;-------------------------------------------------------------------;; Need to to set text colors because version 1.0 of list manager; gets these wrong. ;	PushWord #0	_SetForeColor	PushWord #$000F	_SetBackColor;-------------------------------------------------------------------	lda MemberPtr	clc	adc #5	tax	lda MemberPtr+2	bcc NoCarry	inc aNoCarry	pha	phx	_DrawString	ldy #4	lda [MemberPtr],y	and #$0080	beq NotSelected	pei RectPtr+2	pei RectPtr	_InvertRectNotSelected		;	plb	pld	lda 1,s	sta 13,s	lda 2,s	sta 14,s	tsc	clc	adc #12	tcs	rtl	ENDP	END